package com.secure.documentwallet;

import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;import androidx.fragment.app.FragmentActivity;

public class AccountDevicesActivity extends FragmentActivity {
 @Override public void onCreate(Bundle b){super.onCreate(b);Ui.safeScreen(this);Ui.lightBars(this);if(!Session.valid()){finish();return;}LinearLayout page=VaultPageUi.page(this);page.addView(VaultPageUi.header(this,"Account And Devices","Secure access points"));page.addView(VaultPageUi.section(this,"Your Devices"));String model=Build.MANUFACTURER+" "+Build.MODEL;VaultPageUi.addRow(page,VaultPageUi.row(this,"▯",model,"This device · Active now"));LinearLayout portal=VaultPageUi.row(this,"▣","My Vault PC Portal","Browser access with two-step verification");portal.setOnClickListener(v->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://badimps.github.io/secure-document-wallet/"))));VaultPageUi.addRow(page,portal);page.addView(VaultPageUi.section(this,"Two-Step Verification"));page.addView(VaultPageUi.notice(this,"✓","Email Verification Enabled","A one-time email code is required before the recovery code",Ui.SOFT,Ui.TEAL));TextView pair=VaultPageUi.primary(this,"Open PC Portal");pair.setOnClickListener(v->portal.performClick());VaultPageUi.button(page,pair);setContentView(VaultPageUi.scroll(this,page));}
}
